type Flatten<T extends any[], Acc extends any[] = []> = T extends [infer F, ...infer R] ? (F extends any[] ? Flatten<R, [...Acc, ...Flatten<F>]> : Flatten<R, [...Acc, F]>) : Acc
type CountEl<Arr extends any[], U, C extends unknown[] = []> = Arr extends [infer F, ...infer R] ? (Equal<F, U> extends true ? CountEl<R, U, [...C, unknown]> : CountEl<R, U, C>) : C['length']
type CountElementNumberToObject<T extends any[], F extends any[] = Flatten<T>> = { [K in F[number]]: CountEl<F, K> }

9989.solutionExplanation:
1. 先用 Flatten 拍平嵌套数组，得到全部叶子元素
2. 用映射类型 { [K in F[number]]: ... } 以元素为键建对象，CountEl 统计每个键的出现次数
3. 字符串键 '1' 会被 TS 规范化为数字键 1（匹配测试预期）；never 元素拍平后消失，映射类型自然得到 {}
